package decode

import (
	"encoding/json"
	"strconv"
	"strings"

	"github.com/rakeshnitb23/opfence/internal/classes"
)

// redisFlags are a command's flags in Valkey's command table
// (redis_commands.go, generated by tools/redisgen).
type redisFlags struct {
	write, readOnly, admin, dangerous bool
	// removes says a key spec removes keys or their contents (RM, DELETE).
	removes bool
}

// RedisCommands reads an argument holding Redis commands: a list of
// commands, each a list of words (Upstash's run_redis_commands), or a
// single command. Words may be strings or numbers. ok is false for any
// other shape.
func RedisCommands(v any) (cmds [][]string, ok bool) {
	list, isList := v.([]any)
	if !isList {
		return nil, false
	}
	if len(list) == 0 {
		return nil, true
	}
	if _, nested := list[0].([]any); !nested {
		cmd, ok := redisWords(list)
		if !ok {
			return nil, false
		}
		return [][]string{cmd}, true
	}
	for _, el := range list {
		words, isList := el.([]any)
		if !isList {
			return nil, false
		}
		cmd, ok := redisWords(words)
		if !ok {
			return nil, false
		}
		cmds = append(cmds, cmd)
	}
	return cmds, true
}

func redisWords(list []any) ([]string, bool) {
	out := make([]string, 0, len(list))
	for _, w := range list {
		switch x := w.(type) {
		case string:
			out = append(out, x)
		case json.Number:
			out = append(out, x.String())
		case float64:
			out = append(out, strconv.FormatFloat(x, 'f', -1, 64))
		case bool:
			out = append(out, strconv.FormatBool(x))
		default:
			return nil, false
		}
	}
	return out, true
}

// ClassifyRedis classifies one Redis command (docs/ARCHITECTURE.md §3.4):
// the server's own flags decide, reviewed overrides cover what flags do not
// say, and a command Opfence does not know is unknown.
func ClassifyRedis(cmd []string) []classes.Class {
	if len(cmd) == 0 || strings.TrimSpace(cmd[0]) == "" {
		return one(classes.Unknown)
	}
	name := strings.ToUpper(strings.TrimSpace(cmd[0]))
	args := cmd[1:]
	if strings.HasPrefix(name, "JSON.") {
		return redisJSON(name)
	}
	if redisContainers[name] && len(args) > 0 {
		name += " " + strings.ToUpper(strings.TrimSpace(args[0]))
		args = args[1:]
	}
	if c, ok := redisOverride(name, args); ok {
		return one(c)
	}
	f, known := redisCommands[name]
	switch {
	case !known:
		if redisContainers[name] {
			return one(classes.Read) // the container alone answers with help
		}
		return one(classes.Unknown)
	case f.write && f.removes:
		return one(classes.Delete)
	case f.write:
		return one(classes.Write)
	case f.admin || f.dangerous:
		if redisAdminReads[name] {
			return one(classes.Read)
		}
		return one(classes.Unknown) // server administration a flag cannot describe
	}
	// READONLY, and commands with neither flag: transactions, pub/sub,
	// connection state, introspection.
	return one(classes.Read)
}

// redisOverride decides what the flags cannot: commands that empty a
// database, run code, change access or reveal secrets, and those whose
// effect depends on their arguments.
func redisOverride(name string, args []string) (classes.Class, bool) {
	switch name {
	case "FLUSHALL", "FLUSHDB", "FUNCTION FLUSH":
		return classes.Irreversible, true
	case "EVAL", "EVALSHA", "EVAL_RO", "EVALSHA_RO", "FCALL", "FCALL_RO", "SCRIPT KILL", "FUNCTION KILL",
		"MIGRATE", "CLIENT KILL", "CLIENT PAUSE", "CONFIG SET", "CONFIG REWRITE", "CONFIG RESETSTAT":
		return classes.Unknown, true
	case "PUBLISH", "SPUBLISH", "SCRIPT LOAD", "SCRIPT FLUSH":
		// Not flagged WRITE: a message reaches subscribers, which act on it,
		// and a cached script is what a later EVALSHA runs.
		return classes.Write, true
	case "FUNCTION DELETE":
		return classes.Delete, true
	case "AUTH", "ACL SETUSER", "ACL DELUSER", "ACL LOAD", "ACL SAVE", "ACL SETROLE", "ACL DELROLE":
		return classes.Access, true
	case "ACL LIST", "ACL GETUSER", "ACL GETROLE", "ACL ROLES", "ACL DIGEST", "CONFIG GET", "CONFIG INFO", "MONITOR":
		return classes.Credential, true // password hashes, requirepass, every command's arguments
	case "HELLO":
		for _, a := range args {
			if strings.EqualFold(a, "AUTH") {
				return classes.Access, true
			}
		}
		return classes.Read, true
	case "SORT":
		for _, a := range args {
			if strings.EqualFold(a, "STORE") {
				return classes.Write, true
			}
		}
		return classes.Read, true
	case "EXPIRE", "PEXPIRE":
		// A TTL of zero or less deletes the key at once.
		if len(args) >= 2 && redisNotPositive(args[1]) {
			return classes.Delete, true
		}
		return classes.Write, true
	case "HEXPIRE", "HPEXPIRE":
		if len(args) >= 2 && redisNotPositive(args[1]) {
			return classes.Delete, true
		}
		return classes.Write, true
	case "EXPIREAT", "PEXPIREAT", "HEXPIREAT", "HPEXPIREAT":
		// A time in the past deletes at once; Opfence does not decide by clock.
		return classes.Delete, true
	}
	return "", false
}

// redisNotPositive reports whether a TTL argument is zero or negative, or
// cannot be read (which Redis rejects, but the worse reading counts).
func redisNotPositive(s string) bool {
	n, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	return err != nil || n <= 0
}

// Administration commands that only read.
var redisAdminReads = map[string]bool{
	"KEYS": true, "INFO": true, "LASTSAVE": true, "ROLE": true, "SORT_RO": true,
	"LATENCY DOCTOR": true, "LATENCY GRAPH": true, "LATENCY HISTOGRAM": true, "LATENCY HISTORY": true, "LATENCY LATEST": true,
	"SLOWLOG GET": true, "SLOWLOG LEN": true, "COMMANDLOG GET": true, "COMMANDLOG LEN": true,
	"CLIENT LIST": true, "MODULE LIST": true, "HOTKEYS GET": true,
	"ACL LOG": true, "ACL USERS": true, "ACL DRYRUN": true,
	"CLUSTER COUNT-FAILURE-REPORTS": true, "CLUSTER REPLICAS": true, "CLUSTER SLAVES": true, "CLUSTER GETSLOTMIGRATIONS": true,
}

// redisJSON classifies RedisJSON commands, from the commands Upstash
// documents (upstash.com/docs/redis/commands/json/overview).
func redisJSON(name string) []classes.Class {
	switch name {
	case "JSON.GET", "JSON.MGET", "JSON.TYPE", "JSON.STRLEN", "JSON.ARRLEN", "JSON.ARRINDEX",
		"JSON.OBJKEYS", "JSON.OBJLEN", "JSON.RESP", "JSON.DEBUG":
		return one(classes.Read)
	case "JSON.SET", "JSON.MSET", "JSON.MERGE", "JSON.ARRAPPEND", "JSON.ARRINSERT",
		"JSON.NUMINCRBY", "JSON.NUMMULTBY", "JSON.STRAPPEND", "JSON.TOGGLE":
		return one(classes.Write)
	case "JSON.DEL", "JSON.FORGET", "JSON.CLEAR", "JSON.ARRPOP", "JSON.ARRTRIM":
		return one(classes.Delete)
	}
	return one(classes.Unknown)
}

// ClassifyRedisCommands classifies a list of commands (a pipeline or a
// transaction): the distinct classes of every command, in order.
func ClassifyRedisCommands(cmds [][]string) []classes.Class {
	var out []classes.Class
	seen := map[classes.Class]bool{}
	for _, c := range cmds {
		for _, x := range ClassifyRedis(c) {
			if !seen[x] {
				seen[x] = true
				out = append(out, x)
			}
		}
	}
	return out
}
